// ============================================================
// 1. VALIDATION & NORMALIZATION
// Accepts: channel, customer_id, conversation_id, message_id,
// message, timestamp, customer, metadata.
// Normalizes any channel into: source, customer_id,
// conversation_id, message_id, message, metadata.
// ============================================================
const input = $input.first().json;
const payload = (input && input.body && typeof input.body === 'object' && !Array.isArray(input.body))
  ? input.body
  : input;

const errors = [];

// --- channel validation + mapping -------------------------------
const channelMap = {
  website: 'website', web: 'website', chat: 'website',
  whatsapp: 'whatsapp', telegram: 'telegram', email: 'email',
  slack: 'slack', instagram: 'instagram',
  facebook: 'facebook', messenger: 'facebook', facebook_messenger: 'facebook'
};
let source = '';
const rawChannel = payload && typeof payload.channel === 'string' ? payload.channel.trim().toLowerCase() : '';
if (!rawChannel) {
  errors.push('channel_required');
} else if (channelMap[rawChannel]) {
  source = channelMap[rawChannel];
} else {
  errors.push('invalid_channel');
}

// --- required identifiers ---------------------------------------
const requireId = (name) => {
  const v = payload ? payload[name] : undefined;
  if (v === undefined || v === null || String(v).trim() === '') errors.push(name + '_required');
};
requireId('customer_id');
requireId('conversation_id');
requireId('message_id');

// --- message validation -----------------------------------------
let message = '';
if (!payload || typeof payload.message !== 'string') {
  errors.push('message_required');
} else {
  message = payload.message;
  if (message.trim() === '') errors.push('message_required');
  else if (message.length > 4000) errors.push('message_too_long');
}

// --- timestamp validation ---------------------------------------
let timestamp = new Date().toISOString();
if (payload && payload.timestamp !== undefined && payload.timestamp !== null && payload.timestamp !== '') {
  const ts = new Date(payload.timestamp);
  if (isNaN(ts.getTime())) errors.push('invalid_timestamp');
  else timestamp = ts.toISOString();
}

if (errors.length) {
  return [{ json: { valid: false, errors } }];
}

// ================================================================
// SANITIZATION - treat all input as untrusted
// ================================================================
function sanitize(s, cap) {
  let out = String(s == null ? '' : s);
  out = out.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
  out = out.replace(/\s+/g, ' ').trim();
  if (cap && out.length > cap) out = out.slice(0, cap);
  return out;
}

const sanitizedMessage = sanitize(message, 4000)
  .replace(/(sk-[A-Za-z0-9]{16,})|(AKIA[0-9A-Z]{16})|(xox[baprs]-[A-Za-z0-9-]{10,})|(ghp_[A-Za-z0-9]{20,})/g, '[REDACTED]');

const lowerMsg = sanitizedMessage.toLowerCase();
const injectionPatterns = [
  'ignore previous', 'ignore all previous', 'ignore all instructions',
  'you are now', 'system prompt', 'developer mode', 'reveal your',
  'forget your instructions', 'jailbreak', 'what are your instructions',
  'print your system', 'act as an unrestricted', 'disregard'
];
const security_flags = injectionPatterns.filter(p => lowerMsg.includes(p));

const customer = (payload.customer && typeof payload.customer === 'object') ? payload.customer : {};
const metadata = (payload.metadata && typeof payload.metadata === 'object' && !Array.isArray(payload.metadata)) ? payload.metadata : {};

const envelope = {
  valid: true,
  errors: [],
  source,
  customer_id: sanitize(payload.customer_id, 255),
  conversation_id: sanitize(payload.conversation_id, 255),
  message_id: sanitize(payload.message_id, 255),
  message: sanitizedMessage,
  timestamp,
  customer: {
    name: typeof customer.name === 'string' ? sanitize(customer.name, 255) : '',
    email: typeof customer.email === 'string' ? sanitize(customer.email, 320).toLowerCase() : ''
  },
  metadata,
  security_flags
};

return [{ json: envelope }];

// ============================================================
// 3. IDEMPOTENCY KEY
// Deterministic key from message_id + source, plus an FNV-1a
// content hash. Message IDs are validated upstream.
// ============================================================
const env = $input.first().json;
const key = `${env.source}:${env.message_id}`;

let h = 2166136261;
const str = `${env.message}|${env.customer_id}|${env.conversation_id}|${env.timestamp}`;
for (let i = 0; i < str.length; i++) {
  h ^= str.charCodeAt(i);
  h = Math.imul(h, 16777619);
}
const hash = (h >>> 0).toString(16);

return [{ json: { ...env, idempotency_key: key, idempotency_hash: hash } }];

const rows = $('Check Idempotency').all().map(i => i.json);
const found = rows.length > 0 ? rows[0] : null;
const duplicate = !!(found && found.status === 'completed' && found.payload);
return [{ json: { ...$('Build Idempotency Key').first().json, idempotency_check: found, duplicate } }];

// ============================================================
// 4. DETERMINISTIC POLICY ENGINE
// Critical decisions are rule-based and never rely on the LLM
// alone: low confidence, critical issues, human requests,
// manual refund approval, angry/repeated complaints.
// ============================================================
const env = $input.first().json;
const classification = env.classification || { intent: 'unknown', confidence: 0 };
const sentiment = env.sentiment || { sentiment: 'neutral', priority: 'normal', urgency: 0 };
const confidence = Number(classification.confidence);
const confidenceThreshold = Number(process.env.AI_CONFIDENCE_THRESHOLD || 0.6);
const refundThreshold = Number(process.env.REFUND_APPROVAL_THRESHOLD || 100);

const rules = [];
let action = 'respond';
let priority = sentiment.priority || 'normal';
let requires_human = false;
let refund_above_threshold = false;

// --- refund threshold (manual approval) -------------------------
let refundAmount = null;
const amountMatch = String(env.message || '').match(/\$\s?(\d+(\.\d{1,2})?)/);
if (amountMatch) refundAmount = parseFloat(amountMatch[1]);
if (env.metadata && Number.isFinite(Number(env.metadata.refund_amount))) refundAmount = Number(env.metadata.refund_amount);

if (classification.intent === 'refund_request') {
  rules.push('refund_review');
  if (refundAmount !== null && refundAmount >= refundThreshold) {
    refund_above_threshold = true;
    rules.push('refund_above_threshold');
    action = 'escalate';
    if (priority === 'low' || priority === 'normal') priority = 'high';
  }
}

// --- low confidence -> escalation -------------------------------
if (Number.isFinite(confidence) && confidence < confidenceThreshold) {
  rules.push('low_confidence');
  if (action !== 'escalate') action = 'escalate';
  if (priority === 'normal' || priority === 'low') priority = 'high';
}

// --- explicit human request -------------------------------------
if (classification.intent === 'human_agent_request') {
  rules.push('human_request');
  action = 'escalate';
  requires_human = true;
}

// --- angry / frustrated -> bump priority ------------------------
if (sentiment.sentiment === 'angry' || sentiment.sentiment === 'frustrated') {
  rules.push('negative_sentiment');
  if (priority === 'low' || priority === 'normal') priority = 'high';
}

// --- urgent / critical -> immediate escalation ------------------
if (sentiment.sentiment === 'urgent' || priority === 'critical') {
  rules.push('urgent_issue');
  priority = 'critical';
  action = 'escalate';
  requires_human = true;
}

// --- sensitive intents -> bump priority -------------------------
if (['account_issue', 'payment_issue'].includes(classification.intent)) {
  rules.push('sensitive_intent');
  if (priority === 'low') priority = 'normal';
}

// --- human request keywords in message --------------------------
const lowerMsg = String(env.message || '').toLowerCase();
if (/talk to (a |the )?human|speak to (a |the )?agent|human agent|real person|customer service agent|representative/.test(lowerMsg)) {
  rules.push('human_request_keyword');
  action = 'escalate';
  requires_human = true;
}

// --- unknown intent -> clarify (RAG may still rescue it) --------
if (classification.intent === 'unknown') {
  rules.push('unknown_intent');
  if (action !== 'escalate') action = 'clarify';
}

const policy = {
  action,
  priority,
  requires_human,
  rules,
  confidence,
  confidence_threshold: confidenceThreshold,
  refund_above_threshold,
  refund_amount: refundAmount
};

return [{ json: { ...env, policy } }];

// ============================================================
// 5. RAG POLICY - combine retrieval strength with the action
// decided by the deterministic policy engine.
// strong RAG -> automated response
// weak RAG   -> clarification
// RAG miss   -> clarification (response generator will decide
//               to ask a question or the response validation
//               layer will catch unsupported answers)
// ============================================================
const env = $input.first().json;
const rag = env.rag || { strong: false, weak: false, miss: false };
const policy = env.policy || { action: 'respond', rules: [] };
const rules = Array.isArray(policy.rules) ? policy.rules.slice() : [];
let action = policy.action || 'respond';

if (rag.strong) {
  rules.push('strong_rag_result');
  if (action === 'clarify') action = 'respond';
} else if (rag.weak) {
  rules.push('weak_rag_result');
  if (action === 'respond') action = 'clarify';
} else if (rag.miss) {
  rules.push('rag_miss');
  if (action === 'respond') action = 'clarify';
}

return [{ json: { ...env, policy: { ...policy, action, rules } } }];

// Prepare a single regeneration attempt with the validation
// issues passed back into the prompt.
const env = $input.first().json;
const issues = env.validation && Array.isArray(env.validation.issues) ? env.validation.issues : [];
return [{ json: { ...env, generation_mode: 'regen', validation_issues: issues } }];
